{
    "type": "object",
    "properties": {
        "email": {"type": "string", "description": "Sender email address, when known"},
        "phone": {"type": "string", "description": "Sender phone number (WhatsApp), any format"},
        "name": {"type": "string", "description": "Company or business name given by the customer"}
    },
    "required": []
}

Partner = env['res.partner'].sudo()
internal = env.user.has_group('base.group_user')
digits = ''.join(c for c in (phone or '') if c.isdigit())[-9:]
found = Partner.browse()
if not internal:
    # website visitor: both the email and the phone must belong to the customer
    if email and len(digits) == 9:
        found = Partner.search([('email', '=ilike', email.strip())], limit=5).filtered(
            lambda p: (p.phone_sanitized or '').endswith(digits)
            or (p.commercial_partner_id.phone_sanitized or '').endswith(digits))
else:
    if email:
        found = Partner.search([('email', '=ilike', email.strip())], limit=5)
    if not found and len(digits) == 9:
        found = Partner.search([('phone_sanitized', 'like', digits)], limit=5)
    if not found and name:
        found = Partner.search([('name', 'ilike', name.strip()), ('customer_rank', '>', 0)], limit=5)
locked = env.context.get('ai_order_partner_id')
if locked is not None:
    # email and WhatsApp: the sender is the only customer this conversation may touch
    found = Partner.browse(int(locked or 0)).exists()
customers = found.commercial_partner_id
if internal:
    data = [{
        'partner_id': c.id,
        'name': c.name,
        'city': c.city or '',
        'route': ', '.join(c.category_id.mapped('name')),
        'pricelist': c.property_product_pricelist.name or '',
    } for c in customers]
else:
    data = [{'partner_id': c.id, 'name': c.name} for c in customers]
ai['result'] = {
    'customers': data,
    'note': '' if customers else (
        'No customer matches these details.' if internal
        else 'Ask for the email and the phone number registered with us; both must match.'),
}

{
    "type": "object",
    "properties": {
        "text": {"type": "string", "description": "The product as the customer wrote it, without the quantity"}
    },
    "required": ["text"]
}

{
    "type": "object",
    "properties": {
        "partner_id": {"type": "integer", "description": "Customer id returned by AI Orders: Find customer"},
        "contact_email": {"type": "string", "description": "Email the customer gave in this conversation; required on the website chat"}
    },
    "required": ["partner_id"]
}

partner = env['res.partner'].sudo().browse(int(partner_id or 0)).exists()
# the email may belong to any contact of the customer, not only to the company record
verified = env.user.has_group('base.group_user') or bool(
    partner and contact_email and env['res.partner'].sudo().search_count([
        ('id', 'child_of', partner.commercial_partner_id.id),
        ('email', '=ilike', contact_email.strip())]))
locked = env.context.get('ai_order_partner_id')
if locked is not None:
    verified = bool(partner) and partner.commercial_partner_id == env['res.partner'].sudo().browse(
        int(locked or 0)).commercial_partner_id
if not partner:
    ai['result'] = {'error': 'Unknown partner_id: find the customer first.'}
elif not verified:
    ai['result'] = {'error': 'Identity not verified: ask for the email registered with us.'}
else:
    customer = partner.commercial_partner_id
    orders = env['sale.order'].sudo().search(
        [('partner_id', 'child_of', customer.id), ('state', '=', 'sale')],
        order='date_order desc', limit=8)
    last = orders[:1]
    usual = {}
    for line in orders.order_line.filtered('product_id'):
        usual[line.product_id] = usual.get(line.product_id, 0) + 1
    counts = {}
    peers = env['sale.order.line'].sudo().search([
        ('order_id.state', '=', 'sale'),
        ('order_id.pricelist_id', '=', customer.property_product_pricelist.id),
        ('order_partner_id', '!=', customer.id),
        ('product_id', 'not in', [p.id for p in usual]),
    ], limit=500)
    for line in peers:
        counts[line.product_id] = counts.get(line.product_id, 0) + 1
    suggestions = sorted(counts, key=lambda p: -counts[p])[:3]
    ai['result'] = {
        'customer': customer.name,
        'pricelist': customer.property_product_pricelist.name or '',
        'last_order': last and {
            'name': last.name,
            'date': str(last.date_order.date()),
            'lines': [{
                'product_id': l.product_id.id,
                'product': l.product_id.display_name,
                'quantity': l.product_uom_qty,
                'unit': l.product_uom_id.name,
            } for l in last.order_line if l.product_id],
        } or None,
        'usual_products': [{'product_id': p.id, 'product': p.display_name, 'times_ordered': n}
                           for p, n in sorted(usual.items(), key=lambda kv: -kv[1])[:10]],
        'cross_sell_suggestions': [{'product_id': p.id, 'product': p.display_name}
                                   for p in suggestions],
    }

{
    "type": "object",
    "properties": {
        "partner_id": {"type": "integer", "description": "Customer id"},
        "contact_email": {"type": "string", "description": "Email the customer gave in this conversation; required on the website chat"},
        "product_ids": {"type": "array", "items": {"type": "integer"}, "description": "Product id of each line"},
        "quantities": {"type": "array", "items": {"type": "number"}, "description": "Quantity of each line"},
        "uoms": {"type": "array", "items": {"type": "string"}, "description": "Unit name of each line, from the units returned by AI Orders: Find products"},
        "channel": {"type": "string", "description": "Channel the order came from: web, email or whatsapp"},
        "customer_message": {"type": "string", "description": "The customer's original message, verbatim"},
        "lead_id": {"type": "integer", "description": "Opportunity id when the order arrived by email"}
    },
    "required": ["partner_id", "product_ids", "quantities", "channel"]
}

{
    "type": "object",
    "properties": {
        "quotation": {"type": "string", "description": "Quotation number returned when it was created"},
        "partner_id": {"type": "integer", "description": "Customer id"},
        "contact_email": {"type": "string", "description": "Email the customer gave in this conversation; required on the website chat"},
        "product_ids": {"type": "array", "items": {"type": "integer"}, "description": "Product id of each line to change"},
        "quantities": {"type": "array", "items": {"type": "number"}, "description": "New quantity of each product, 0 to remove it"},
        "uoms": {"type": "array", "items": {"type": "string"}, "description": "Unit name of each line, empty for the product unit"},
        "customer_confirmed": {"type": "boolean", "description": "True when the customer has confirmed the summary"}
    },
    "required": ["quotation", "partner_id"]
}

partner = env['res.partner'].sudo().browse(int(partner_id or 0)).exists()
# the email may belong to any contact of the customer, not only to the company record
verified = env.user.has_group('base.group_user') or bool(
    partner and contact_email and env['res.partner'].sudo().search_count([
        ('id', 'child_of', partner.commercial_partner_id.id),
        ('email', '=ilike', contact_email.strip())]))
locked = env.context.get('ai_order_partner_id')
if locked is not None:
    verified = bool(partner) and partner.commercial_partner_id == env['res.partner'].sudo().browse(
        int(locked or 0)).commercial_partner_id
order = env['sale.order'].sudo().search([('name', '=', (quotation or '').strip())], limit=1)
pids = product_ids or []
qtys = quantities or []
units = uoms or []
if not partner or not verified or not order or order.partner_id.commercial_partner_id != partner.commercial_partner_id:
    ai['result'] = {'error': 'Quotation not found for this customer.'}
elif order.state not in ('draft', 'sent'):
    ai['result'] = {'error': 'The quotation is already validated: changes go through the team.'}
elif len(pids) != len(qtys):
    ai['result'] = {'error': 'product_ids and quantities must have the same length.'}
else:
    Product = env['product.product'].sudo()
    Uom = env['uom.uom'].sudo()
    for i in range(len(pids)):
        product = Product.browse(int(pids[i])).exists()
        if not product or not product.sale_ok:
            continue
        qty = float(qtys[i] or 0)
        line = order.order_line.filtered(lambda l: l.product_id == product)[:1]
        uom = line.product_uom_id or product.uom_id
        wanted = i < len(units) and (units[i] or '').strip()
        if wanted:
            candidate = Uom.search([('name', '=ilike', wanted)], limit=1)
            if candidate and (candidate == product.uom_id or candidate.relative_uom_id == product.uom_id):
                uom = candidate
        if line and qty <= 0:
            line.unlink()
        elif line:
            line.write({'product_uom_qty': qty, 'product_uom_id': uom.id})
        elif qty > 0:
            order.write({'order_line': [(0, 0, {'product_id': product.id, 'product_uom_qty': qty,
                                                'product_uom_id': uom.id})]})
    if customer_confirmed:
        order.write({'tag_ids': [(4, env.ref('pc_ai_order_intake.crm_tag_customer_confirmed').id)]})
        order.message_post(body='The customer confirmed the order summary.', subtype_xmlid='mail.mt_note')
    ai['result'] = {
        'quotation': order.name,
        'portal_url': order.get_base_url() + order.get_portal_url(),
        'customer_confirmed': bool(customer_confirmed),
        'lines': [{
            'product': l.product_id.display_name,
            'quantity': l.product_uom_qty,
            'unit': l.product_uom_id.name,
            'subtotal': l.price_subtotal,
        } for l in order.order_line],
        'untaxed_total': order.amount_untaxed,
        'total': order.amount_total,
    }
